#include<bits/stdc++.h>
using namespace std;using P=pair<int,int>;map<P,int>last;int dirs[4][2]={{0,1},{1,0},{0,-1},{-1,0}};string names="DCV",words[]={"LLLLRLRRRR","LLLLRLRRRRLRRRR","LLLLRLRRRRLRRLRRRR"},mark="LLLLRLRRRRL";long long nodes=0,cap;int depth;bool stop=false,hit=false;vector<long long>levels;string path;mt19937 rng;bool randomize;
P rot(P p,int h){while(h--)p={p.second,-p.first};return p;}
bool run(string w,P&p,int&h,vector<pair<P,int>>&u){for(char c:w){int bit=c=='L';auto it=last.find(p);int old=it==last.end()?-1:it->second;if(old==bit)return false;u.push_back({p,old});last[p]=bit;h=(h+(bit?3:1))%4;p.first+=dirs[h][0];p.second+=dirs[h][1];}return true;}
void undo(vector<pair<P,int>>&u){for(auto it=u.rbegin();it!=u.rend();++it)if(it->second<0)last.erase(it->first);else last[it->first]=it->second;}
void dfs(P p,int h){if(++nodes>cap){stop=true;return;}levels[path.size()]++;if(path.size()==depth)return;array<int,3>order={0,1,2};if(randomize)shuffle(order.begin(),order.end(),rng);for(int a:order){P z=rot({1,2},h);z.first+=p.first;z.second+=p.second;P z2=rot({0,3},h);z2.first+=p.first;z2.second+=p.second;bool stale=last.count(z)&&last.count(z2);P q=p;int hh=h;vector<pair<P,int>>u;if(run(words[a],q,hh,u)){path+=names[a];P pp=q;int hhh=hh;vector<pair<P,int>>v;bool marked=run(mark,pp,hhh,v);undo(v);if(marked&&a==2&&stale){cout<<"HIT "<<path<<" nose "<<z.first<<" "<<z.second<<" nodes "<<nodes<<endl;stop=hit=true;}if(marked&&!stop)dfs(q,hh);path.pop_back();}undo(u);if(stop)return;}}
int main(int argc,char**argv){depth=stoi(argv[1]);cap=stoll(argv[2]);randomize=argc>3;if(randomize)rng.seed(stoi(argv[3]));levels.resize(depth+1);dfs({0,0},0);cout<<"FINISH nodes "<<nodes<<" cap "<<(stop&&!hit)<<" hit "<<hit<<" levels";for(auto a:levels)cout<<" "<<a;cout<<endl;}
